# Scored file: encrypt_payload.py\n# Uses AWS KMS to encrypt a plaintext payload with a managed key\n\nimport os\nimport json\nimport boto3\nfrom botocore.exceptions import ClientError\n\nfrom security_client import get_kms_client\nfrom security_models import PlaintextPayload, EncryptedResult\n\ndef encrypt(payload: str) -> EncryptedResult:\n    \"\"\"Encrypt a plaintext payload using AWS KMS envelope encryption.\n\n    Returns a dict containing the encrypted data key and the ciphertext.\n    \"\"\"\n    client = get_kms_client()\n    # Define the target KMS key (could be a CMK ARN)\n    key_id = os.getenv(\"AWS_KMS_KEY_ID\")\n    if not key_id:\n        raise RuntimeError(\"AWS_KMS_KEY_ID environment variable not set\")\n\n    try:\n        # Generate a data key (plaintext and ciphertext)\n        resp = client.generate_data_key(\n            KeyId=key_id,\n            KeySpec='AES_256'\n        )\n        plaintext_key = resp['Plaintext']  # bytes\n        encrypted_key = resp['CiphertextBlob']  # bytes\n\n        # Encrypt the payload using the plaintext data key (local AES)\n        ciphertext = _aes_encrypt(payload.encode('utf-8'), plaintext_key)\n        return EncryptedResult(\n            encrypted_data_key=encrypted_key,\n            ciphertext=ciphertext\n        )\n    except ClientError as e:\n        raise RuntimeError(f\"KMS error: {e}\") from e\n\ndef _aes_encrypt(data: bytes, key: bytes) -> bytes:\n    # Simple AES-256-CBC encryption with PKCS#7 padding\n    from Crypto.Cipher import AES\n    from Crypto.Util.Padding import pad\n    iv = os.urandom(16)\n    cipher = AES.new(key, AES.MODE_CBC, iv)\n    ct = cipher.encrypt(pad(data, AES.block_size))\n    return iv + ct\n\nif __name__ == \"__main__\":\n    sample = \"This is a secret message.\"\n    result = encrypt(sample)\n    print(json.dumps(result, default=str))\n